// Guard the boundary with the analytics service.
//
// The HTTP node already fails on a non-2xx status. What it cannot judge is
// whether a 200 response is the payload we expect. Throwing here stops the
// workflow, so a malformed response can never be finalised as a clean run.

const body = $input.first().json;

if (body === null || typeof body !== 'object') {
  throw new Error(`Analytics service returned a ${typeof body} rather than a JSON object`);
}

for (const field of ['dates_evaluated', 'dates_written', 'dates_incomplete_kpi']) {
  if (typeof body[field] !== 'number') {
    throw new Error(
      `Analytics service response is missing numeric "${field}". ` +
      `Keys present: ${Object.keys(body).join(', ') || '<none>'}`
    );
  }
}

if (!body.detector_version) {
  throw new Error('Analytics service response carries no detector_version');
}

// Every evaluated date must produce a result row - scored or explicitly
// unscored. A shortfall means results were silently dropped.
if (body.dates_written !== body.dates_evaluated) {
  throw new Error(
    `Detector wrote ${body.dates_written} results for ${body.dates_evaluated} ` +
    `evaluated dates - some were lost`
  );
}

return [{ json: body }];
